<?php require __DIR__.'/app/layout.php';must_admin();$id=(int)($_GET['edit']??0);$edit=$id?one_row('SELECT * FROM users WHERE id=?',[$id]):null;
if($id&&!$edit){flash('Utilisateur introuvable.','danger');go('utilisateurs.php');}
$rows=all_rows('SELECT u.id,u.name,u.email,u.role,u.legacy_post,u.active, (SELECT COUNT(*) FROM reservations r WHERE r.user_id=u.id) AS reservation_count FROM users u ORDER BY u.id');
page_start('Utilisateurs','users');titlebar('Administration','Gestion des utilisateurs','Contrôlez les accès et les comptes de la plateforme.'); ?>
<div class="row g-4"><div class="col-xl-4"><div class="panel"><div class="panel-head"><h3><?= $edit?'Modifier un compte':'Créer un compte' ?></h3><?php if($edit):?><a class="btn btn-sm btn-light border" href="<?=h(url('utilisateurs.php'))?>">Nouveau</a><?php endif;?></div><form method="post" action="<?=h(url('actions.php'))?>"><?=csrf_field()?><input type="hidden" name="action" value="user_save"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><div class="mb-3"><label class="form-label">Nom *</label><input class="form-control" name="name" required maxlength="150" value="<?=h($edit['name']??'')?>"></div><div class="mb-3"><label class="form-label">Email (facultatif pour anciens comptes)</label><input type="email" name="email" class="form-control" value="<?=h($edit['email']??'')?>"></div><div class="mb-3"><label class="form-label">Rôle</label><select class="form-select" name="role"><option value="user" <?=($edit['role']??'user')==='user'?'selected':''?>>Utilisateur</option><option value="admin" <?=($edit['role']??'')==='admin'?'selected':''?>>Administrateur</option></select></div><div class="mb-4"><label class="form-label"><?= $edit?'Nouveau mot de passe (vide = inchangé)':'Mot de passe *' ?></label><input class="form-control" type="password" name="password" autocomplete="new-password" minlength="10" <?= $edit?'':'required' ?>><div class="form-text">10 caractères minimum.</div></div><?php submit_button($edit?'Enregistrer les modifications':'Ajouter l’utilisateur');?></form></div></div>
<div class="col-xl-8"><div class="panel"><div class="panel-head"><h3>Comptes (<?=count($rows)?>)</h3></div><input class="form-control mb-3" data-table-search placeholder="Rechercher un utilisateur…"><div class="table-responsive"><table class="table"><thead><tr><th>Compte</th><th>Rôle</th><th>Réservations</th><th>État</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $u):?><tr data-search-row><td><strong><?=h($u['name'])?></strong><div class="muted small"><?=h($u['email']?:'Identifiant : '.$u['id'])?></div></td><td><?=h($u['role']==='admin'?'Administrateur':'Utilisateur')?><?php if($u['legacy_post']):?><div class="muted small">Ancien poste : <?=h($u['legacy_post'])?></div><?php endif;?></td><td><?=h($u['reservation_count'])?></td><td><span class="badge <?= $u['active']?'text-bg-success':'text-bg-secondary' ?>"><?= $u['active']?'Actif':'Désactivé' ?></span></td><td><div class="d-flex gap-1"><a href="<?=h(url('utilisateurs.php?edit='.$u['id']))?>" class="btn btn-sm btn-outline-primary"><i class="bi bi-pencil"></i></a><?php if((int)$u['id']!==(int)me()['id']):?><form method="post" action="<?=h(url('actions.php'))?>" data-confirm="Changer l’état de ce compte ?"><?=csrf_field()?><input type="hidden" name="action" value="user_toggle"><input type="hidden" name="id" value="<?=h($u['id'])?>"><button class="btn btn-sm btn-outline-warning"><i class="bi bi-<?= $u['active']?'person-x':'person-check' ?>"></i></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php page_end();?>
